-- Proposed scoped specialization §§7.2/8.5/21.4/25.3/51.2/51.6.
-- Fresh private request-local context, not a caller-controlled composite.
CREATE DOMAIN public.kcml_operation_context_v1 AS uuid;
CREATE FUNCTION public.kcml_owner_query_context_v1(p_ctx public.kcml_operation_context_v1)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE data jsonb; r record;
BEGIN
 SELECT c.relowner INTO r FROM pg_catalog.pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND c.relname='kcml_verified_owner_query';
 IF r.relowner IS DISTINCT FROM (SELECT oid FROM pg_catalog.pg_roles WHERE rolname='kcml_authentication_writer') THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='OWNER_QUERY_TRUSTED_CONTEXT_REQUIRED';END IF;
 SELECT to_jsonb(t) INTO data FROM pg_temp.kcml_verified_owner_query t WHERE t.id=p_ctx::uuid AND t.transaction_id=pg_current_xact_id() AND t.backend_id=pg_backend_pid();
 IF data IS NULL THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='OWNER_QUERY_TRUSTED_CONTEXT_REQUIRED';END IF;
 IF current_setting('transaction_isolation')<>'repeatable read' OR current_setting('transaction_read_only')<>'on' THEN RAISE EXCEPTION USING ERRCODE='25000',MESSAGE='OWNER_QUERY_PROFILE_MISMATCH';END IF;
 RETURN data;
END$$;
CREATE FUNCTION public.kcml_assert_operation_descriptor_v1(p_ctx public.kcml_operation_context_v1,p_operation text,p_descriptor text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c jsonb=public.kcml_owner_query_context_v1(p_ctx);expected text;
BEGIN
 expected=CASE p_operation WHEN 'ownerApiKey.read' THEN 'sha256:294f62dc44b546f270df88f825c37f9402db88b7e56f7099a449b9f446cf5770' WHEN 'ownerApiKey.reveal' THEN 'sha256:e2b589e43911d76901b71da890c6c85978d2fa2ae9158ae8a9b0b6dbe6da3275' END;
 IF expected IS NULL THEN RAISE EXCEPTION USING ERRCODE='0A000',MESSAGE='SQL_OPERATION_TYPED_HANDLER_UNRESOLVED';END IF;
 IF (c->>'operation_id',c->>'descriptor_digest')IS DISTINCT FROM(p_operation,expected) OR p_descriptor IS DISTINCT FROM expected THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='OWNER_QUERY_DESCRIPTOR_MISMATCH';END IF;
END$$;
CREATE FUNCTION public.kcml_assert_recovery_and_incarnation_v1(p_ctx public.kcml_operation_context_v1)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c jsonb=public.kcml_owner_query_context_v1(p_ctx);pi public.platform_incarnation;dh public.application_deployment_head;s public.owner_session;o public.owner_identity;
BEGIN
 SELECT * INTO STRICT pi FROM public.platform_incarnation WHERE singleton_key=1;
 SELECT * INTO STRICT dh FROM public.application_deployment_head WHERE singleton_key=1;
 SELECT * INTO STRICT o FROM public.owner_identity WHERE singleton_key=1;
 IF (pi.platform_incarnation_id::text,dh.platform_incarnation_id::text,dh.application_deployment_epoch::text,o.id::text) IS DISTINCT FROM(c->>'incarnation',c->>'incarnation',c->>'deployment_epoch',c->>'owner_id') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='OWNER_QUERY_SNAPSHOT_AUTHORITY_MISMATCH';END IF;
 IF c->>'access_channel'='OWNER_SESSION' THEN
 SELECT * INTO s FROM public.owner_session WHERE id=(c->>'session_id')::uuid;
 IF s.id IS NULL OR s.owner_identity_id<>o.id OR s.session_epoch<>o.session_epoch OR s.revoked_at IS NOT NULL OR s.expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='OWNER_SESSION_STALE';END IF;
 ELSIF c->>'access_channel'<>'OWNER_API_KEY' THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='OWNER_QUERY_ACCESS_CHANNEL_INVALID'; END IF;
 -- CONSISTENT_READ has no mutation/recovery-READY claim and acquires no E lock.
END$$;
CREATE FUNCTION public.kcml_lock_exact_root_plan_v1(p_ctx public.kcml_operation_context_v1,p_root text,p_ordinal text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c jsonb=public.kcml_owner_query_context_v1(p_ctx);a public.owner_api_credential;r kcml_secret_v1.secret_record;v kcml_secret_v1.secret_version;
BEGIN
 IF p_root<>'owner_api_credential' OR p_ordinal<>'' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='OWNER_QUERY_PHYSICAL_PLAN_MISMATCH';END IF;
 SELECT * INTO STRICT a FROM public.owner_api_credential WHERE singleton_key=1;
 SELECT * INTO r FROM kcml_secret_v1.secret_record WHERE id=a.secret_id;
 SELECT * INTO v FROM kcml_secret_v1.secret_version WHERE id=a.secret_version_id AND secret_id=a.secret_id;
 IF (a.secret_id::text,a.secret_version_id::text,a.credential_version::text,a.credential_activation_epoch::text,a.fingerprint)IS DISTINCT FROM(c->>'secret_id',c->>'secret_version_id',c->>'credential_version',c->>'credential_epoch',c->>'fingerprint') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='OWNER_QUERY_CREDENTIAL_BINDING_MISMATCH';END IF;
 IF r.stable_name IS DISTINCT FROM 'KCML_OWNER_API_KEY' OR r.secret_type IS DISTINCT FROM 'API_KEY' OR r.active_version_id IS DISTINCT FROM v.id OR v.secret_type IS DISTINCT FROM 'API_KEY' OR v.lifecycle IS DISTINCT FROM 'ACTIVE' OR v.fingerprint IS DISTINCT FROM a.fingerprint OR kcml_secret_v1.record_status_v1(r.id)IS DISTINCT FROM 'ACTIVE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='OWNER_QUERY_CREDENTIAL_ROOT_NOT_ACTIVE';END IF;
END$$;
CREATE FUNCTION public.kcml_owner_query_expected_plan_v1(p_operation text)RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT CASE p_operation
 WHEN 'ownerApiKey.read' THEN '{"operationId":"ownerApiKey.read","profile":"CONSISTENT_READ","subjectTable":"owner_api_credential","rootOwnershipRef":"owner_api_credential","mode":"READ","physicalPhases":["READ_ONLY_SNAPSHOT"],"rootLockPlan":{"root":"owner_api_credential","lockClass":"E_PARENT_AGGREGATE","ordinal":null,"auditHeadLast":true},"fieldUpdatePlan":[{"semanticField":"`singleton_key = OWNER_API`, primary/unique a check constraint","storage":"EXPLICIT_COLUMN_WHERE_SOURCE_OR_CONSTRAINT_NAMES_COLUMN_ELSE_ENTITY_CONTRACT_PAYLOAD_JSONB","requiredBySource":true},{"semanticField":"`secret_id` a `secret_version_id` pro stable name `KCML_OWNER_API_KEY`","storage":"EXPLICIT_COLUMN_WHERE_SOURCE_OR_CONSTRAINT_NAMES_COLUMN_ELSE_ENTITY_CONTRACT_PAYLOAD_JSONB","requiredBySource":true},{"semanticField":"`verifier_hash`, `fingerprint`, `credential_version`","storage":"EXPLICIT_COLUMN_WHERE_SOURCE_OR_CONSTRAINT_NAMES_COLUMN_ELSE_ENTITY_CONTRACT_PAYLOAD_JSONB","requiredBySource":true},{"semanticField":"`state_version` a credential activation epoch","storage":"EXPLICIT_COLUMN_WHERE_SOURCE_OR_CONSTRAINT_NAMES_COLUMN_ELSE_ENTITY_CONTRACT_PAYLOAD_JSONB","requiredBySource":true},{"semanticField":"poslední rotate logical operation a outcome digest","storage":"EXPLICIT_COLUMN_WHERE_SOURCE_OR_CONSTRAINT_NAMES_COLUMN_ELSE_ENTITY_CONTRACT_PAYLOAD_JSONB","requiredBySource":true},{"semanticField":"`created_at`, `rotated_at`, `last_used_at`","storage":"EXPLICIT_COLUMN_WHERE_SOURCE_OR_CONSTRAINT_NAMES_COLUMN_ELSE_ENTITY_CONTRACT_PAYLOAD_JSONB","requiredBySource":true},{"semanticField":"`last_usage_metadata`, `audit_correlation_id`","storage":"EXPLICIT_COLUMN_WHERE_SOURCE_OR_CONSTRAINT_NAMES_COLUMN_ELSE_ENTITY_CONTRACT_PAYLOAD_JSONB","requiredBySource":true},{"semanticField":"Existuje právě jeden řádek a jedna active Secret version. Tabulka neobsahuje account relation, principal, role, scope, label, expiry ani collection lifecycle. Rotace pod singleton row lockem a expected state version atomicky nahradí active Secret version, verifier, credential version a epoch; předchozí klíč přestane platit v témže commitu. Retry stejné rotate logical operation vrací stejný canonical outcome.","storage":"EXPLICIT_COLUMN_WHERE_SOURCE_OR_CONSTRAINT_NAMES_COLUMN_ELSE_ENTITY_CONTRACT_PAYLOAD_JSONB","requiredBySource":true}],"applicableDatabaseRuleIds":["db.decl.SSOT-DECL-198.4","db.sql.ssot-202"],"compositeForeignKeyPolicy":"APPLY_ALL_SOURCE_RULES_WHOSE_TABLE_SET_INTERSECTS_SUBJECT_OR_ROOT; NONE_IF_EMPTY","deferredTriggerPolicy":"APPLY_SOURCE_DECLARED_DEFERRED_TRIGGER_RULES_BEFORE_TERMINAL_COMMIT","stateVersionPolicy":"CAS_REQUIRED_FOR_MUTATION; READ_ONLY_FOR_CONSISTENT_READ","externalIoInsideSql":false,"sourceRefs":[{"section":"51.2","anchor":"section.51.2","sourceDigest":"sha256:0ae1f03f89fe347e8b88c8181728d1b6dfe4b86214481f36ea0da9db01bfab12","relation":"AUTHORITY"},{"section":"51.5","anchor":"section.51.5","sourceDigest":"sha256:0ae1f03f89fe347e8b88c8181728d1b6dfe4b86214481f36ea0da9db01bfab12","relation":"AUTHORITY"},{"section":"51.6","anchor":"section.51.6","sourceDigest":"sha256:0ae1f03f89fe347e8b88c8181728d1b6dfe4b86214481f36ea0da9db01bfab12","relation":"AUTHORITY"},{"section":"51.30","anchor":"section.51.30","sourceDigest":"sha256:0ae1f03f89fe347e8b88c8181728d1b6dfe4b86214481f36ea0da9db01bfab12","relation":"AUTHORITY"}]}'::jsonb
 WHEN 'ownerApiKey.reveal' THEN '{"operationId":"ownerApiKey.reveal","profile":"CONSISTENT_READ","subjectTable":"owner_api_credential","rootOwnershipRef":"owner_api_credential","mode":"READ","physicalPhases":["READ_ONLY_SNAPSHOT"],"rootLockPlan":{"root":"owner_api_credential","lockClass":"E_PARENT_AGGREGATE","ordinal":null,"auditHeadLast":true},"fieldUpdatePlan":[{"semanticField":"`singleton_key = OWNER_API`, primary/unique a check constraint","storage":"EXPLICIT_COLUMN_WHERE_SOURCE_OR_CONSTRAINT_NAMES_COLUMN_ELSE_ENTITY_CONTRACT_PAYLOAD_JSONB","requiredBySource":true},{"semanticField":"`secret_id` a `secret_version_id` pro stable name `KCML_OWNER_API_KEY`","storage":"EXPLICIT_COLUMN_WHERE_SOURCE_OR_CONSTRAINT_NAMES_COLUMN_ELSE_ENTITY_CONTRACT_PAYLOAD_JSONB","requiredBySource":true},{"semanticField":"`verifier_hash`, `fingerprint`, `credential_version`","storage":"EXPLICIT_COLUMN_WHERE_SOURCE_OR_CONSTRAINT_NAMES_COLUMN_ELSE_ENTITY_CONTRACT_PAYLOAD_JSONB","requiredBySource":true},{"semanticField":"`state_version` a credential activation epoch","storage":"EXPLICIT_COLUMN_WHERE_SOURCE_OR_CONSTRAINT_NAMES_COLUMN_ELSE_ENTITY_CONTRACT_PAYLOAD_JSONB","requiredBySource":true},{"semanticField":"poslední rotate logical operation a outcome digest","storage":"EXPLICIT_COLUMN_WHERE_SOURCE_OR_CONSTRAINT_NAMES_COLUMN_ELSE_ENTITY_CONTRACT_PAYLOAD_JSONB","requiredBySource":true},{"semanticField":"`created_at`, `rotated_at`, `last_used_at`","storage":"EXPLICIT_COLUMN_WHERE_SOURCE_OR_CONSTRAINT_NAMES_COLUMN_ELSE_ENTITY_CONTRACT_PAYLOAD_JSONB","requiredBySource":true},{"semanticField":"`last_usage_metadata`, `audit_correlation_id`","storage":"EXPLICIT_COLUMN_WHERE_SOURCE_OR_CONSTRAINT_NAMES_COLUMN_ELSE_ENTITY_CONTRACT_PAYLOAD_JSONB","requiredBySource":true},{"semanticField":"Existuje právě jeden řádek a jedna active Secret version. Tabulka neobsahuje account relation, principal, role, scope, label, expiry ani collection lifecycle. Rotace pod singleton row lockem a expected state version atomicky nahradí active Secret version, verifier, credential version a epoch; předchozí klíč přestane platit v témže commitu. Retry stejné rotate logical operation vrací stejný canonical outcome.","storage":"EXPLICIT_COLUMN_WHERE_SOURCE_OR_CONSTRAINT_NAMES_COLUMN_ELSE_ENTITY_CONTRACT_PAYLOAD_JSONB","requiredBySource":true}],"applicableDatabaseRuleIds":["db.decl.SSOT-DECL-198.4","db.sql.ssot-202"],"compositeForeignKeyPolicy":"APPLY_ALL_SOURCE_RULES_WHOSE_TABLE_SET_INTERSECTS_SUBJECT_OR_ROOT; NONE_IF_EMPTY","deferredTriggerPolicy":"APPLY_SOURCE_DECLARED_DEFERRED_TRIGGER_RULES_BEFORE_TERMINAL_COMMIT","stateVersionPolicy":"CAS_REQUIRED_FOR_MUTATION; READ_ONLY_FOR_CONSISTENT_READ","externalIoInsideSql":false,"sourceRefs":[{"section":"51.2","anchor":"section.51.2","sourceDigest":"sha256:0ae1f03f89fe347e8b88c8181728d1b6dfe4b86214481f36ea0da9db01bfab12","relation":"AUTHORITY"},{"section":"51.5","anchor":"section.51.5","sourceDigest":"sha256:0ae1f03f89fe347e8b88c8181728d1b6dfe4b86214481f36ea0da9db01bfab12","relation":"AUTHORITY"},{"section":"51.6","anchor":"section.51.6","sourceDigest":"sha256:0ae1f03f89fe347e8b88c8181728d1b6dfe4b86214481f36ea0da9db01bfab12","relation":"AUTHORITY"},{"section":"51.30","anchor":"section.51.30","sourceDigest":"sha256:0ae1f03f89fe347e8b88c8181728d1b6dfe4b86214481f36ea0da9db01bfab12","relation":"AUTHORITY"}]}'::jsonb END$$;
REVOKE ALL ON FUNCTION public.kcml_owner_query_expected_plan_v1(text)FROM PUBLIC;
CREATE FUNCTION public.kcml_apply_exact_domain_plan_v1(p_ctx public.kcml_operation_context_v1,p_plan jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c jsonb=public.kcml_owner_query_context_v1(p_ctx);a public.owner_api_credential;r kcml_secret_v1.secret_record;v kcml_secret_v1.secret_version;
BEGIN
 IF p_plan->>'operationId' IS DISTINCT FROM c->>'operation_id' OR p_plan->>'profile'<>'CONSISTENT_READ' OR p_plan->>'mode'<>'READ' OR p_plan->>'subjectTable'<>'owner_api_credential' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='OWNER_QUERY_TYPED_PLAN_MISMATCH';END IF;
 IF p_plan IS DISTINCT FROM public.kcml_owner_query_expected_plan_v1(c->>'operation_id') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='OWNER_QUERY_EXACT_PLAN_MISMATCH';END IF;
 -- No fieldUpdatePlan/slot/storage fallback interpreter. Exact static projection.
 PERFORM public.kcml_assert_recovery_and_incarnation_v1(p_ctx);
 PERFORM public.kcml_lock_exact_root_plan_v1(p_ctx,'owner_api_credential','');
 SELECT * INTO STRICT a FROM public.owner_api_credential WHERE singleton_key=1;
 IF c->>'operation_id'='ownerApiKey.read' THEN
 RETURN jsonb_build_object('secretId',a.secret_id,'secretVersionId',a.secret_version_id,'fingerprint',a.fingerprint,'credentialVersion',a.credential_version::text,'credentialActivationEpoch',a.credential_activation_epoch::text,'createdAt',to_char(a.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'rotatedAt',to_char(a.rotated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'lastUsedAt',to_char(a.last_used_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 ELSIF c->>'operation_id'='ownerApiKey.reveal' THEN
 SELECT * INTO STRICT v FROM kcml_secret_v1.secret_version WHERE id=a.secret_version_id AND secret_id=a.secret_id;
 -- INTERNAL decryptor input only; no verifier or full row reflection. A service
 -- must hydrate authenticated bytes and bind canonical key/nonce authority.
 RETURN jsonb_build_object('secretId',v.secret_id,'secretVersionId',v.id,'representation',v.value_representation,'plaintextByteLength',v.plaintext_byte_length,'ciphertextHex',encode(v.ciphertext,'hex'),'nonceHex',encode(v.nonce,'hex'),'algorithm',v.algorithm,'keyId',v.key_id,'creatorContextId',v.creator_context_id,'fingerprint',v.fingerprint,'originalImportBytesDigest','sha256:'||encode(v.original_import_bytes_digest,'hex'),'canonicalValueDigest','sha256:'||encode(v.canonical_value_digest,'hex'));
 END IF;
 RAISE EXCEPTION USING ERRCODE='0A000',MESSAGE='SQL_OPERATION_TYPED_HANDLER_UNRESOLVED';
END$$;
REVOKE ALL ON FUNCTION public.kcml_owner_query_context_v1(public.kcml_operation_context_v1),public.kcml_assert_operation_descriptor_v1(public.kcml_operation_context_v1,text,text),public.kcml_assert_recovery_and_incarnation_v1(public.kcml_operation_context_v1),public.kcml_lock_exact_root_plan_v1(public.kcml_operation_context_v1,text,text),public.kcml_apply_exact_domain_plan_v1(public.kcml_operation_context_v1,jsonb) FROM PUBLIC;
-- Fixture migration owner is not a runtime credential/role choice. Coordinator
-- must map to existing trusted read-only/acceptance group and grants explicitly.
